#include <Cellerator/compiler/ir/planning/implement_planning_ir_parser_printer_and_validator_v1.hh>
#include <cassert>
#include <cstring>
int main(){using namespace cellerator::compiler::ir::planning::v1;const char ext[]="future.foo=7 unknown.bar={x}";planning_text_module_v1 a{{1,2},3,4,5,6,7,8,ext,sizeof(ext)-1};char text[512];std::size_t n=0;assert(print_planning_ir_v1(a,text,sizeof text,&n)==planning_text_status_v1::ok);char saved[128];planning_text_module_v1 b{};assert(parse_planning_ir_v1(text,n,saved,sizeof saved,&b)==planning_text_status_v1::ok);assert(b.module.low==a.module.low&&b.selections==a.selections&&b.unknown_extension_bytes==a.unknown_extension_bytes&&!std::memcmp(saved,ext,sizeof(ext)-1));char text2[512];std::size_t n2=0;assert(print_planning_ir_v1(b,text2,sizeof text2,&n2)==planning_text_status_v1::ok&&n==n2&&!std::memcmp(text,text2,n));for(unsigned i=0;i<256;++i){char fuzz[8]={(char)i,'x','x','x','x','x','x','x'};assert(parse_planning_ir_v1(fuzz,sizeof fuzz,saved,sizeof saved,&b)!=planning_text_status_v1::ok);}}
